(7100424, 1081682, 62357, '<td valign="top">This is wonderful Ben.   Timing is perfect.</td>', 'This is wonderful Ben.   Timing is perfect.', '2013-09-08 05:52:52.000000', NULL, 0),
(7100425, 1081390, 108580, '<td valign="top">As someone who takes natural scapes (when I am out in the field) I recognised the blue colour was smoke and not odd PP. We are just coming out of our winter where this is common place all over Africa, unless it''s dust, then the results are reddish. Underrated. 7.</td>', 'As someone who takes natural scapes (when I am out in the field) I recognised the blue colour was smoke and not odd PP. We are just coming out of our winter where this is common place all over Africa, unless it''s dust, then the results are reddish. Underrated. 7.', '2013-09-08 05:53:43.000000', NULL, 0),
(7100428, 1081697, 16148, '<td valign="top">Love the candidness and ease of this image.  The low contrast reveals plenty.  Thanks</td>', 'Love the candidness and ease of this image.  The low contrast reveals plenty.  Thanks', '2013-09-08 06:03:32.000000', NULL, 0),
(7100430, 1081682, 16148, '<td valign="top">Youth!  A wonderful time and timing.</td>', 'Youth!  A wonderful time and timing.', '2013-09-08 06:05:55.000000', NULL, 0),
