(7100436, 1079790, 61396, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by RKT:</b></div><hr/><i> It''s a modern day "Le déjeuner sur l''herbe"...nice catch. </i></td></tr></table> <br/><a href="//en.wikipedia.org/wiki/Le_d%C3%A9jeuner_sur_l''herbe" rel="nofollow" target="_blank">according to wikipedia</a>, the original title of Manet''s "Le déjeuner sur l''herbe" (The Luncheon on the Grass) was "Le Bain" (The Bath). How very fitting.</td>', 'Originally posted by RKT: It''s a modern day "Le déjeuner sur l''herbe"...nice catch.  according to wikipedia, the original title of Manet''s "Le déjeuner sur l''herbe" (The Luncheon on the Grass) was "Le Bain" (The Bath). How very fitting.', '2013-09-08 06:12:36.000000', NULL, 0),
(7100437, 1081562, 16148, '<td valign="top">Just enough information to let the mind wonder.  Beautifully composed!</td>', 'Just enough information to let the mind wonder.  Beautifully composed!', '2013-09-08 06:14:12.000000', NULL, 0),
(7100438, 1080439, 16148, '<td valign="top">What posthumous said.  Love it!</td>', 'What posthumous said.  Love it!', '2013-09-08 06:15:21.000000', NULL, 0),
(7100439, 1080955, 16148, '<td valign="top">Breaking from the pack.  Interesting shot!</td>', 'Breaking from the pack.  Interesting shot!', '2013-09-08 06:24:54.000000', NULL, 0),
(7100440, 1080960, 108580, '<td valign="top">Gut wrenching to be given a 5.5 average. I on the other hand obviously erred by awarding it an 8! Wonderful image Steve and this is gallery worthy. Print it and hang it in your entrance.</td>', 'Gut wrenching to be given a 5.5 average. I on the other hand obviously erred by awarding it an 8! Wonderful image Steve and this is gallery worthy. Print it and hang it in your entrance.', '2013-09-08 06:26:41.000000', NULL, 0),
(7100441, 1081652, 16148, '<td valign="top">Very interesting!  Nice find or creation?</td>', 'Very interesting!  Nice find or creation?', '2013-09-08 06:28:25.000000', NULL, 0),
(7100444, 1081637, 108580, '<td valign="top">WD on your HM. I must say I have shot with the Olympus OM-D EM5 and it is IMO a fabulous small form factor camera to rival DSLR''s. 8.</td>', 'WD on your HM. I must say I have shot with the Olympus OM-D EM5 and it is IMO a fabulous small form factor camera to rival DSLR''s. 8.', '2013-09-08 06:39:48.000000', NULL, 0),
(7100445, 1081644, 108580, '<td valign="top">Congrats on your HM. There was a softness about this that threw me a little. It is still a fabulous image. 7.</td>', 'Congrats on your HM. There was a softness about this that threw me a little. It is still a fabulous image. 7.', '2013-09-08 06:41:19.000000', NULL, 0),
